for _code, _words in {
    "en": {"Ein schneller und komfortabler Bildbetrachter": "A fast and convenient image viewer"},
    "fr": {"Ein schneller und komfortabler Bildbetrachter": "Une visionneuse d’images rapide et pratique"},
    "es": {"Ein schneller und komfortabler Bildbetrachter": "Un visor de imágenes rápido y cómodo"},
    "uk": {"Ein schneller und komfortabler Bildbetrachter": "Швидкий і зручний переглядач зображень"},
}.items():
    CATALOGUE[_code].update(_words)

def language_code(value: str | None) -> str:
    return value if value in LANGUAGES else "de"

def t(source: str) -> str:
    translated = QCoreApplication.translate("BildBlick", source)
    if translated != source:
        return translated
    return CATALOGUE.get(_language, {}).get(source, SPECIAL_TEXTS.get(_language, {}).get(source, source))

class LanguageManager(QObject):
    def __init__(self, settings: QSettings) -> None:
        super().__init__()
        self.settings = settings
        self.set_language(settings.value(LANGUAGE_KEY, "de", type=str), persist=False)

    @property
    def code(self) -> str: return _language

    def set_language(self, code: str, *, persist: bool = True) -> None:
        global _language
        _language = language_code(code)
        if persist:
            self.settings.setValue(LANGUAGE_KEY, _language); self.settings.sync()
        app = QApplication.instance()
        if app:
            for widget in app.topLevelWidgets():
                self.translate_widget_tree(widget)

    def translate_widget_tree(self, root: QWidget) -> None:
        for widget in [root, *root.findChildren(QWidget)]:
            if isinstance(widget, (QDialog, QMainWindow)):
                source = widget.property("bildblickSourceWindowTitle") or widget.windowTitle()
                if source:
                    widget.setProperty("bildblickSourceWindowTitle", source); widget.setWindowTitle(t(source))
            if isinstance(widget, (QLabel, QPushButton, QToolButton, QCheckBox)):
                source = widget.property("bildblickSourceText") or widget.text()
                widget.setProperty("bildblickSourceText", source); widget.setText(t(source))
            elif isinstance(widget, QGroupBox):
                source = widget.property("bildblickSourceTitle") or widget.title()
                widget.setProperty("bildblickSourceTitle", source); widget.setTitle(t(source))
            tooltip = widget.property("bildblickSourceToolTip") or widget.toolTip()
            if tooltip:
                widget.setProperty("bildblickSourceToolTip", tooltip); widget.setToolTip(t(tooltip))
            if isinstance(widget, QComboBox):
                sources = widget.property("bildblickSourceItems")
                if not sources:
                    sources = [widget.itemText(index) for index in range(widget.count())]
                    widget.setProperty("bildblickSourceItems", sources)
                for index, source in enumerate(sources):
                    widget.setItemText(index, t(source))
        for action in root.findChildren(QAction):
            source = action.property("bildblickSourceText") or action.text()
            action.setProperty("bildblickSourceText", source); action.setText(t(source))
            tooltip = action.property("bildblickSourceToolTip") or action.toolTip()
            if tooltip:
                action.setProperty("bildblickSourceToolTip", tooltip); action.setToolTip(t(tooltip))
        for menu in root.findChildren(QMenu):
            source = menu.property("bildblickSourceTitle") or menu.title()
            menu.setProperty("bildblickSourceTitle", source); menu.setTitle(t(source))
        refresh_i18n = getattr(root, "refresh_i18n", None)
        if callable(refresh_i18n):
            refresh_i18n()
